// Copy-as helpers — convert a captured HTTP request into a cURL /
// PowerShell / Python-requests one-liner that can be pasted into a
// terminal and reproduce the original call.
//
// Design notes:
// - Every builder consumes a parsed `RequestForCopy` so the three
//   outputs stay in sync; one source of truth drives all three.
// - Shell/PowerShell/Python each need their own quoting rules —
//   centralised in `*Quote()` helpers so a single edit fixes all
//   call sites.
// - Headers like `Content-Length` and `Host` are regenerated by the
//   target tool itself, so we drop them to keep the output readable
//   and reduce the "stale header" footguns operators run into when
//   they tweak the body before replaying.

import { StoredSummary } from "./api";

/** Parsed request ready for any Copy-as builder. */
export type RequestForCopy = {
  url: string;
  method: string;
  headers: Array<[string, string]>;
  body: string;
};

/** Headers that each target tool recomputes from the URL / body, so we
 *  omit them to keep the pasted command tidy and avoid header drift. */
const SKIP_HEADERS = new Set([
  "content-length",
  "host",
  "connection",
  "accept-encoding",
]);

/** Build an absolute URL from a stored summary row. */
export function urlFromSummary(s: StoredSummary): string {
  const defaultPort =
    (s.scheme === "https" && s.port === 443) ||
    (s.scheme === "http" && s.port === 80);
  const authority = defaultPort ? s.host : `${s.host}:${s.port}`;
  return `${s.scheme}://${authority}${s.path}`;
}

/**
 * Split a raw wire-format request into method + headers + body.
 * Tolerates both CRLF and bare LF line endings.
 */
export function parseRawRequest(raw: string): {
  method: string;
  path: string;
  headers: Array<[string, string]>;
  body: string;
} {
  // Normalise to LF so one split handles both styles.
  const text = raw.replace(/\r\n/g, "\n");
  const headerEnd = text.indexOf("\n\n");
  const headerBlock = headerEnd >= 0 ? text.slice(0, headerEnd) : text;
  const body = headerEnd >= 0 ? text.slice(headerEnd + 2) : "";
  const lines = headerBlock.split("\n");
  const startLine = (lines.shift() ?? "").trim();
  const [method = "GET", path = "/"] = startLine.split(/\s+/);
  const headers: Array<[string, string]> = [];
  for (const l of lines) {
    const colon = l.indexOf(":");
    if (colon <= 0) continue;
    const name = l.slice(0, colon).trim();
    const value = l.slice(colon + 1).trim();
    if (!name) continue;
    headers.push([name, value]);
  }
  return { method, path, headers, body };
}

/** Build a `RequestForCopy` from a StoredSummary + the raw text of its
 *  request. `raw` can be omitted if the caller only has the summary;
 *  the resulting command will be headers-free. */
export function fromSummaryAndRaw(
  summary: StoredSummary,
  raw?: string,
): RequestForCopy {
  const url = urlFromSummary(summary);
  if (!raw) {
    return { url, method: summary.method, headers: [], body: "" };
  }
  const parsed = parseRawRequest(raw);
  const headers = parsed.headers.filter(
    ([n]) => !SKIP_HEADERS.has(n.toLowerCase()),
  );
  return { url, method: parsed.method || summary.method, headers, body: parsed.body };
}

/** Build a `RequestForCopy` from an explicit URL + raw wire-format text. */
export function fromUrlAndRaw(url: string, raw: string): RequestForCopy {
  const parsed = parseRawRequest(raw);
  const headers = parsed.headers.filter(
    ([n]) => !SKIP_HEADERS.has(n.toLowerCase()),
  );
  return { url, method: parsed.method || "GET", headers, body: parsed.body };
}

// ---------------------------------------------------------------------------
// Quoting
// ---------------------------------------------------------------------------

/** POSIX-shell single-quote escaping — safe for cURL and `data` args. */
function shQuote(s: string): string {
  // Replace embedded ' with '\'' so the shell concatenates two
  // single-quoted strings and a literal apostrophe.
  return `'${s.replace(/'/g, `'\\''`)}'`;
}

/** PowerShell single-quote escaping — doubles the apostrophe. */
function psQuote(s: string): string {
  return `'${s.replace(/'/g, `''`)}'`;
}

/** Python single-quoted string with backslash + apostrophe escapes.
 *  Non-printable bytes get escaped as \xNN so the resulting string
 *  literal pastes cleanly even if the body contained binary. */
function pyQuote(s: string): string {
  let out = "";
  for (const ch of s) {
    const code = ch.charCodeAt(0);
    if (ch === "\\") out += "\\\\";
    else if (ch === "'") out += "\\'";
    else if (ch === "\n") out += "\\n";
    else if (ch === "\r") out += "\\r";
    else if (ch === "\t") out += "\\t";
    else if (code < 0x20 || code === 0x7f) out += `\\x${code.toString(16).padStart(2, "0")}`;
    else out += ch;
  }
  return `'${out}'`;
}

// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------

/** cURL command, line-broken for readability. */
export function buildCurl(req: RequestForCopy): string {
  const parts: string[] = [`curl ${shQuote(req.url)}`];
  if (req.method && req.method.toUpperCase() !== "GET") {
    parts.push(`-X ${req.method.toUpperCase()}`);
  }
  for (const [name, value] of req.headers) {
    parts.push(`-H ${shQuote(`${name}: ${value}`)}`);
  }
  if (req.body && req.body.length > 0) {
    parts.push(`--data-raw ${shQuote(req.body)}`);
  }
  parts.push(`--compressed`);
  return parts.join(" \\\n  ");
}

/** PowerShell `Invoke-WebRequest` command.
 *  Prefers `Invoke-WebRequest` over `Invoke-RestMethod` so the
 *  operator still sees the raw status + headers alongside the body. */
export function buildPowerShell(req: RequestForCopy): string {
  const parts: string[] = [`Invoke-WebRequest -Uri ${psQuote(req.url)}`];
  if (req.method && req.method.toUpperCase() !== "GET") {
    parts.push(`-Method ${req.method.toUpperCase()}`);
  }
  if (req.headers.length > 0) {
    const kv = req.headers
      .map(([n, v]) => `${psQuote(n)} = ${psQuote(v)}`)
      .join("; ");
    parts.push(`-Headers @{ ${kv} }`);
  }
  if (req.body && req.body.length > 0) {
    parts.push(`-Body ${psQuote(req.body)}`);
  }
  // -UseBasicParsing is required on Windows PowerShell 5.x and harmless on 7+.
  parts.push(`-UseBasicParsing`);
  return parts.join(" `\n  ");
}

/** Python 3 `requests` call. Produces a top-level `requests.<verb>(…)`
 *  snippet with headers as a dict and body as a `data=` kwarg (or
 *  `json=` when the Content-Type is JSON). */
export function buildPython(req: RequestForCopy): string {
  const method = (req.method || "GET").toLowerCase();
  // requests only exposes short-form helpers for the common verbs.
  const useVerb = ["get", "post", "put", "delete", "patch", "head", "options"].includes(method);
  const callee = useVerb
    ? `requests.${method}`
    : `requests.request(${pyQuote(method.toUpperCase())}, `;
  const openParen = useVerb ? "(\n    " : "\n    ";
  const closeParen = useVerb ? ",\n)" : ",\n)";
  const argLead = useVerb ? "" : "";

  const lines: string[] = [];
  lines.push(`${pyQuote(req.url)}`);

  if (req.headers.length > 0) {
    const dictLines = req.headers
      .map(([n, v]) => `        ${pyQuote(n)}: ${pyQuote(v)},`)
      .join("\n");
    lines.push(`headers={\n${dictLines}\n    }`);
  }

  if (req.body && req.body.length > 0) {
    const isJson = req.headers.some(
      ([n, v]) => n.toLowerCase() === "content-type" && v.toLowerCase().includes("json"),
    );
    // Attempt a JSON object for application/json so the output is
    // idiomatic; fall back to raw bytes if the body isn't valid JSON.
    if (isJson) {
      try {
        const parsed = JSON.parse(req.body);
        const pretty = JSON.stringify(parsed, null, 4)
          .split("\n")
          .map((l, i) => (i === 0 ? l : `    ${l}`))
          .join("\n");
        lines.push(`json=${pretty}`);
      } catch {
        lines.push(`data=${pyQuote(req.body)}`);
      }
    } else {
      lines.push(`data=${pyQuote(req.body)}`);
    }
  }

  const body = argLead + lines.join(",\n    ");
  return `import requests\n\nresp = ${callee}${openParen}${body}${closeParen}\nprint(resp.status_code, resp.headers)\nprint(resp.text)`;
}

/** R148: Browser `fetch()` snippet. Operators who paste the request
 *  into a devtools console (or a JS test harness) get a modern,
 *  idiomatic reproduction. Headers go in a plain object; body is
 *  `JSON.stringify` for JSON content-type, raw string otherwise.
 *  Credentials: `include` so cookies replay as the browser would. */
export function buildFetch(req: RequestForCopy): string {
  const method = (req.method || "GET").toUpperCase();
  const parts: string[] = [`  method: ${JSON.stringify(method)}`];
  parts.push(`  credentials: "include"`);
  if (req.headers.length > 0) {
    const items = req.headers
      .map(([n, v]) => `    ${JSON.stringify(n)}: ${JSON.stringify(v)}`)
      .join(",\n");
    parts.push(`  headers: {\n${items}\n  }`);
  }
  if (req.body && req.body.length > 0) {
    const isJson = req.headers.some(
      ([n, v]) => n.toLowerCase() === "content-type" && v.toLowerCase().includes("json"),
    );
    if (isJson) {
      try {
        const parsed = JSON.parse(req.body);
        parts.push(`  body: JSON.stringify(${JSON.stringify(parsed, null, 2)
          .split("\n")
          .map((l, i) => (i === 0 ? l : `  ${l}`))
          .join("\n")})`);
      } catch {
        parts.push(`  body: ${JSON.stringify(req.body)}`);
      }
    } else {
      parts.push(`  body: ${JSON.stringify(req.body)}`);
    }
  }
  return `const resp = await fetch(${JSON.stringify(req.url)}, {\n${parts.join(",\n")}\n});\nconsole.log(resp.status, Object.fromEntries(resp.headers));\nconsole.log(await resp.text());`;
}

/** Convenience: write a Copy-as string to the clipboard with a
 *  single toast-friendly success/fail Promise. */
export async function copyToClipboard(text: string): Promise<void> {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return;
  }
  // Fallback for environments without the async clipboard API.
  const ta = document.createElement("textarea");
  ta.value = text;
  ta.style.position = "fixed";
  ta.style.left = "-10000px";
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand("copy");
  } finally {
    document.body.removeChild(ta);
  }
}

// ---------------------------------------------------------------------------
// R453: HAR (HTTP Archive 1.2) bulk builder.
// ---------------------------------------------------------------------------
// HAR is an open standard defined by the W3C Web Performance WG for
// exchanging HTTP captures between tools (browsers, intercepting
// proxies, test harnesses). Unlike the per-request builders above
// (cURL / PowerShell / Python / fetch), HAR is a container format
// — one top-level JSON object holds an array of entries — so this
// builder is bulk-first by design. Each entry carries request +
// (optional) response + timings; BurpFree's history has request
// metadata on every row but not always a stored response body, so
// we populate response fields opportunistically and leave the rest
// at HAR's "unknown" sentinels (`headersSize: -1`, `bodySize: -1`,
// empty cache object, zero timings).

/** One HAR entry's optional response pair. Caller supplies only what
 *  it has; missing fields collapse to HAR's "unknown" sentinels. */
export type HarResponseOpt = {
  status?: number;
  statusText?: string;
  httpVersion?: string;
  headers?: Array<[string, string]>;
  mimeType?: string;
  body?: string;
};

/** One entry of a HAR log, assembled from a parsed request + the
 *  optional response pair + the timestamp the capture started.
 *  `startedDateTime` must be ISO-8601 with millisecond precision —
 *  matches what Chrome / Firefox DevTools emit so downstream HAR
 *  viewers (har-viewer, httptoolkit, etc.) accept the output. */
export function buildHarEntry(
  req: RequestForCopy,
  startedDateTime: string,
  resp?: HarResponseOpt,
): object {
  // HAR's `queryString[]` wants URL params decomposed. Use URL
  // when the input parses; fall back to an empty array otherwise.
  let queryString: Array<{ name: string; value: string }> = [];
  try {
    const u = new URL(req.url);
    u.searchParams.forEach((value, name) => {
      queryString.push({ name, value });
    });
  } catch { /* non-absolute URL — leave queryString empty */ }

  const reqHeaders = req.headers.map(([name, value]) => ({ name, value }));
  const respHeaders = (resp?.headers ?? []).map(([name, value]) => ({ name, value }));

  // HAR cookies[] can repeat the Cookie / Set-Cookie headers but
  // most consumers only read the top-level headers array. Keep the
  // output minimal; downstream tooling that wants parsed cookies
  // walks the headers array itself.
  return {
    startedDateTime,
    time: 0,
    request: {
      method: (req.method || "GET").toUpperCase(),
      url: req.url,
      httpVersion: "HTTP/1.1",
      headers: reqHeaders,
      queryString,
      cookies: [],
      headersSize: -1,
      bodySize: req.body?.length ?? 0,
      ...(req.body && req.body.length > 0
        ? {
            postData: {
              mimeType:
                req.headers.find(
                  ([n]) => n.toLowerCase() === "content-type",
                )?.[1] ?? "application/octet-stream",
              text: req.body,
            },
          }
        : {}),
    },
    response: {
      status: resp?.status ?? 0,
      statusText: resp?.statusText ?? "",
      httpVersion: resp?.httpVersion ?? "HTTP/1.1",
      headers: respHeaders,
      cookies: [],
      content: {
        size: resp?.body?.length ?? 0,
        mimeType: resp?.mimeType ?? "",
        ...(resp?.body ? { text: resp.body } : {}),
      },
      redirectURL: "",
      headersSize: -1,
      bodySize: resp?.body?.length ?? 0,
    },
    cache: {},
    timings: { send: 0, wait: 0, receive: 0 },
  };
}

/** Build a complete HAR log from a list of entries. The returned
 *  object is JSON.stringify-ready; callers typically do
 *  `JSON.stringify(buildHarLog(entries), null, 2)` for a human-
 *  readable file + `copyToClipboard` for a one-tap paste. */
export function buildHarLog(entries: object[]): object {
  return {
    log: {
      version: "1.2",
      creator: {
        name: "BurpFree",
        version: "0.1.0",
        comment: "exported from HistoryPanel bulk Copy-as-HAR (R453)",
      },
      entries,
    },
  };
}
